from pathlib import Path
from collections import Counter
import json, base64, html

ROOT=Path(__file__).parent
layout=json.loads((ROOT/'생활보장과_사무실배치.json').read_text(encoding='utf-8'))
counts=Counter(i[0] for i in layout['items'])
occupied={}
for index,(kind,x,y,w,h,direction,label) in enumerate(layout['items']):
    assert 0<=x and 0<=y and x+w<=layout['cols'] and y+h<=layout['rows']
    assert direction in ('up','down','left','right')
    for yy in range(y,y+h):
        for xx in range(x,x+w):
            assert (xx,yy) not in occupied, '배치 중첩'
            occupied[xx,yy]=index

